import sys

def solve(n, m, a, b):
    def backtrack(row, col, grid):
        if row == n:
            return True
        if col == m:
            return backtrack(row + 1, 0, grid)
        for c in ['.', '*']:
            grid[row][col] = c
            if is_valid(grid, row, col, a, b):
                if backtrack(row, col + 1, grid):
                    return True
        grid[row][col] = '.'
        return False

    def is_valid(grid, row, col, a, b):
        if not check_row(grid, row, a[row]):
            return False
        if not check_col(grid, col, b[col]):
            return False
        return True

    def check_row(grid, row, expected_segments):
        count = 0
        current_segment = 0
        for cell in grid[row]:
            if cell == '*':
                current_segment += 1
            else:
                if current_segment > 0:
                    count += 1
                current_segment = 0
        if current_segment > 0:
            count += 1
        return count == expected_segments

    def check_col(grid, col, expected_segments):
        count = 0
        current_segment = 1
        for r in range(n):
            if grid[r][col] == '*':
                current_segment += 1
            else:
                if grid[r][col] == '.' and current_segment > 1:
                    count += 1
                current_segment = 1
        if current_segment > 1:
            count += 1
        return count == expected_segments

    grid = [['.' for _ in range(m)] for _ in range(n)]
    if backtrack(0, 0, grid):
        return '\n'.join(''.join(row) for row in grid)

input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
a = list(map(int, input[2:2+n]))
b = list(map(int, input[2+n:2+n+m]))
print(solve(n, m, a, b))
